import { memo } from "react";

/**
 * Counts `DiffBlock` render executions for `DiffBlock.test.tsx`'s memo
 * regression (the component is a leaf with no child component to mock,
 * so the suite's child-mock memo test is impossible here): the memo
 * skips this body entirely on an identical-props re-render.
 */
let renderCount = 0;
export const diffBlockRenderCount = (): number => renderCount;

/**
 * Renders a unified patch string (red/green line-based). No diff library —
 * the patch is already generated by the store reducer (`unifiedPatch`).
 *
 * Memoized at the export below (issue #155): both props are strings, so `memo`'s
 * shallow compare is a VALUE compare, and a re-render carrying the identical
 * patch skips the `patch.split("\n")` and the per-line map entirely.
 */
function DiffBlock({
  path,
  patch,
}: {
  path: string;
  patch: string;
}) {
  renderCount += 1;
  const lines = patch.split("\n");

  return (
    <div className="overflow-hidden rounded-md bg-surface">
      <div className="border-b border-border px-3 py-1.5 font-mono text-ui-sm text-foreground-subtle">
        {path}
      </div>
      <pre className="overflow-x-auto p-2 font-mono text-sm leading-5">
        {lines.map((line, i) => {
          let cls = "text-foreground-subtle";
          if (line.startsWith("+") && !line.startsWith("+++")) {
            cls = "text-diff-added";
          } else if (line.startsWith("-") && !line.startsWith("---")) {
            cls = "text-diff-removed";
          } else if (line.startsWith("@@")) {
            cls = "text-icon-blue";
          }
          return (
            <div key={i} className={cls}>
              {line === "" ? " " : line}
            </div>
          );
        })}
      </pre>
    </div>
  );
}

export default memo(DiffBlock);
